import{c as r,Q as d,j as o,m as e}from"./chunks/framework.rWdQudnF.js";const b=JSON.parse('{"title":"指令系统和流水处理","description":"","frontmatter":{"title":"指令系统和流水处理"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/指令系统和流水处理.md","filePath":"综合知识/系统基础/计算机组成/指令系统和流水处理.md","lastUpdated":null}'),a={name:"综合知识/系统基础/计算机组成/指令系统和流水处理.md"};function n(s,t,l,h,i,g){return d(),o("div",null,[...t[0]||(t[0]=[e('<h3 id="flynn-分类法" tabindex="-1">Flynn 分类法 <a class="header-anchor" href="#flynn-分类法" aria-label="Permalink to &quot;Flynn 分类法&quot;">​</a></h3><blockquote><p>按<strong>指令流</strong>和<strong>数据流</strong>的多倍性将计算机分为 4 类。</p></blockquote><table tabindex="0"><thead><tr><th>分类</th><th>说明</th><th>典型代表</th></tr></thead><tbody><tr><td><strong>SISD</strong></td><td>单指令流单数据流</td><td>传统单处理器、冯·诺依曼机器</td></tr><tr><td><strong>SIMD</strong></td><td>单指令流多数据流</td><td>阵列处理机、并行处理机</td></tr><tr><td><strong>MISD</strong></td><td>多指令流单数据流</td><td><strong>极少见</strong>（有文献将流水线归为此类）</td></tr><tr><td><strong>MIMD</strong></td><td>多指令流多数据流</td><td>多核计算机、多处理机、超级计算机</td></tr></tbody></table><blockquote><p>当前主流多核计算机属于 <strong>MIMD</strong>。</p></blockquote><h3 id="指令系统-cisc-和-risc" tabindex="-1">指令系统 CISC 和 RISC <a class="header-anchor" href="#指令系统-cisc-和-risc" aria-label="Permalink to &quot;指令系统 CISC 和 RISC&quot;">​</a></h3><h4 id="cisc-vs-risc" tabindex="-1">CISC vs RISC <a class="header-anchor" href="#cisc-vs-risc" aria-label="Permalink to &quot;CISC vs RISC&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260518215620.png" alt="image.png"></p><table tabindex="0"><thead><tr><th>对比</th><th>CISC（复杂指令集）</th><th>RISC（精简指令集）</th></tr></thead><tbody><tr><td>指令数量</td><td>多</td><td>少</td></tr><tr><td>指令长度</td><td><strong>可变</strong></td><td>固定</td></tr><tr><td>实现方式</td><td>微程序控制</td><td><strong>组合逻辑</strong>（硬件实现）</td></tr><tr><td>寻址方式</td><td>多样</td><td>少</td></tr><tr><td>寄存器</td><td>少</td><td><strong>大量寄存器</strong></td></tr><tr><td>执行时间</td><td>差别大</td><td>多数单周期</td></tr></tbody></table><h4 id="指令组成与执行" tabindex="-1">指令组成与执行 <a class="header-anchor" href="#指令组成与执行" aria-label="Permalink to &quot;指令组成与执行&quot;">​</a></h4><blockquote><p>一条指令 = <strong>操作码</strong>（决定操作类型）+ <strong>地址码</strong>（操作数地址）。整条指令以二进制编码存放。</p></blockquote><p><strong>执行三阶段</strong>：取指令（PC→地址总线，从内存取）→ 分析指令（ID 解析操作码）→ 执行指令。</p><h4 id="寻址方式" tabindex="-1">寻址方式 <a class="header-anchor" href="#寻址方式" aria-label="Permalink to &quot;寻址方式&quot;">​</a></h4><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th>特点</th></tr></thead><tbody><tr><td><strong>顺序寻址</strong></td><td>一条接一条顺序执行</td><td>下一条地址由 PC 给出</td></tr><tr><td><strong>跳跃寻址</strong></td><td>下条地址由本条指令直接给出</td><td>PC 内容相应改变</td></tr></tbody></table><p><strong>操作数寻址方式：</strong></p><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th style="text-align:center;">速度</th></tr></thead><tbody><tr><td><strong>立即寻址</strong></td><td>地址码直接包含操作数本身</td><td style="text-align:center;">—</td></tr><tr><td><strong>直接寻址</strong></td><td>地址码是操作数的内存地址</td><td style="text-align:center;">—</td></tr><tr><td><strong>间接寻址</strong></td><td>地址码指向存有操作数地址的单元</td><td style="text-align:center;">慢</td></tr><tr><td><strong>寄存器寻址</strong></td><td>操作数在寄存器中</td><td style="text-align:center;"><strong>最快</strong></td></tr><tr><td><strong>基址寻址</strong></td><td>基址寄存器 + 形式地址 → 有效地址</td><td style="text-align:center;">用于静态数据</td></tr><tr><td><strong>变址寻址</strong></td><td>变址寄存器 + 形式地址 → 有效地址</td><td style="text-align:center;">用于数组/动态数据</td></tr></tbody></table><h3 id="指令的流水处理" tabindex="-1">指令的流水处理 <a class="header-anchor" href="#指令的流水处理" aria-label="Permalink to &quot;指令的流水处理&quot;">​</a></h3><h4 id="流水线原理" tabindex="-1">流水线原理 <a class="header-anchor" href="#流水线原理" aria-label="Permalink to &quot;流水线原理&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260518215701.png" alt="image.png"></p><ul><li>RISC中的流水线技术：超流水线（在每个机器周期内能完成一个甚至两个浮点操作，以时间换空间)、超标量（内装多条流水线同时执行多个处理，以空间换时间）、超长指令字 VLIW (同时执行多条指令，发挥软件作用)。</li></ul><h4 id="流水线时间计算" tabindex="-1">流水线时间计算 <a class="header-anchor" href="#流水线时间计算" aria-label="Permalink to &quot;流水线时间计算&quot;">​</a></h4><p><strong>流水线核心公式：</strong></p><table tabindex="0"><thead><tr><th>指标</th><th>公式</th></tr></thead><tbody><tr><td><strong>流水线周期</strong></td><td>各段中<strong>执行时间最长的段</strong>的时间</td></tr><tr><td><strong>执行时间</strong></td><td>1条指令总执行时间 +（总指令条数 - 1）× 流水线周期</td></tr><tr><td><strong>吞吐率</strong></td><td>指令条数 / 流水线执行时间</td></tr><tr><td><strong>加速比</strong></td><td>不使用流水线执行时间 / 使用流水线执行时间</td></tr></tbody></table><ul><li>流水线周期：指令分成不同执行段，其中执行时间最长的段为流水线周期。</li><li>流水线执行时间：1条指令总执行时间+（总指令条数-1）* 流水线周期。</li><li>单缓冲区和双缓冲区：此类题型不给出具体流水线执行阶段，<strong>需要考生自己区分出流水线阶段</strong>，一般来说，能够同时执行的阶段就是流水线的独立执行阶段：只能独立执行的阶段应该合并为流水线中的一个独立执行阶段。</li></ul><p>例如有三个阶段即读入缓冲区+送入用户区+数据处理，在单缓冲区中，缓冲区和用户区都只有一个，一个盘块必须执行完前两个阶段，下一个盘块才能开始，因此前两个阶段应该合并，整个流水线为送入用户区+数据处理；</p><p>而在双缓冲区中，盘块可以交替读入缓冲区，但用户区只有一个，因为缓冲区阶段可以同时进行，流水线前两个阶段不能合并，就是读入缓冲区+送入用户区+数据处理三段。</p><p>划分出真正的流水线阶段后，套用流水线时间计算公式可以轻易得出答案。</p><ul><li>流水线吞吐率计算：吞吐率即单位时间内执行的指令条数。公式：指令条数/流水线执行时间。</li><li>流水线的加速比计算：加速比即使用流水线后的效率提升度，即比不使用流水线快了多少倍，越高表明流水线效率越高，公式：不使用流水线执行时间/使用流水线执行时间。</li></ul><h3 id="指令流水线" tabindex="-1">指令流水线 <a class="header-anchor" href="#指令流水线" aria-label="Permalink to &quot;指令流水线&quot;">​</a></h3><blockquote><p>将指令分成不同段，每段由不同部件并行处理。</p></blockquote><p><strong>RISC 流水线三种技术：</strong></p><table tabindex="0"><thead><tr><th>技术</th><th>核心理念</th><th>本质</th></tr></thead><tbody><tr><td><strong>超流水线</strong></td><td>细化流水、增加级数、提高主频</td><td><strong>时间换空间</strong></td></tr><tr><td><strong>超标量</strong></td><td>多条流水线同时执行多个处理</td><td><strong>空间换时间</strong></td></tr><tr><td><strong>超长指令字（VLIW）</strong></td><td>软件调度并行，简化硬件</td><td>软件发挥主要作用</td></tr></tbody></table><h3 id="超线程技术-hyper-threading" tabindex="-1">超线程技术（Hyper-Threading） <a class="header-anchor" href="#超线程技术-hyper-threading" aria-label="Permalink to &quot;超线程技术（Hyper-Threading）&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>超线程让一个物理核心模拟两个逻辑核心</strong>，共享执行资源，提高 CPU 并行计算能力。</p></blockquote><ul><li>一个物理核心配备两套寄存器组和中断逻辑，操作系统看到&quot;两个核心&quot;</li><li>共享物理执行单元（ALU、Cache 等），并非真正的双核</li><li>适合多线程负载，单线程密集型收益有限</li><li>属于提高 CPU 并行计算能力的技术（区别于加密/压缩/缓存技术）</li></ul>',34)])])}const p=r(a,[["render",n]]);export{b as __pageData,p as default};
